 foreach(['min','max'] as $k)if(($_GET[$k]??'')!==''){$where[]='o.total_minor'.($k==='min'?'>=':'<=').'?';$args[]=minor($_GET[$k],cfg()['max_amount_minor']);}
 $tail=' WHERE '.implode(' AND ',$where);
 if(($_GET['export']??'')==='csv'){
  header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="pina-market-registry.csv"');$f=fopen('php://output','wb');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,['Номер','Клиент','Email','Тип','Статус','Дата','Сумма RUB','Комиссия RUB','Итого RUB','Сервис','Получатель','Зачислено RUB','Банковское поступление','Пояснение','Подтверждение исполнения'],';', '"','');db()->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,false);$s=query(op_select().$tail.' ORDER BY o.number DESC',$args);while($o=$s->fetch()){$snapshot=json_decode($o['snapshot_json'],true);$values=[$o['number'],$o['client_id'],$o['email'],$o['kind'],$o['status'],iso($o['created_at']),number_format((int)$o['amount_minor']/100,2,'.',''),number_format((int)$o['fee_minor']/100,2,'.',''),number_format((int)$o['total_minor']/100,2,'.',''),$snapshot['name']??'',$o['recipient'],$o['kind']==='deposit'&&$o['status']==='completed'?number_format((int)$o['total_minor']/100,2,'.',''):'',$o['bank_reference']??'',$o['result_text'],$snapshot['executionProof']??''];$values=array_map(fn($v)=>preg_match('/^[=+@\-\t\r\n]/',(string)$v)?"'".$v:$v,$values);fputcsv($f,$values,';','"','');}fclose($f);exit;
 }
 $n=(int)one('SELECT COUNT(*) n FROM pm_operations o JOIN pm_clients c ON c.id=o.client_id'.$tail,$args)['n'];[$page,$pages,$offset]=pagination($n);return ['items'=>array_map('op_json',rows(op_select().$tail.' ORDER BY o.number DESC LIMIT 20 OFFSET '.$offset,$args)),'page'=>$page,'pages'=>$pages,'count'=>$n];
