function admin_operation(int $id,array $d,array $actor):void {
 transact(function()use($id,$d,$actor){$o=one('SELECT * FROM pm_operations WHERE number=? FOR UPDATE',[$id]);if(!$o)throw new ApiError('Заявка не найдена',404);$c=one('SELECT * FROM pm_clients WHERE id=? FOR UPDATE',[$o['client_id']]);$action=txt($d,'action',30);$status=$o['status'];$assigned=$o['assigned_to'];$bankref=$o['bank_reference'];$result=$o['result_text'];$balance=(int)$c['balance_minor'];$reserved=(int)$c['reserved_minor'];$total=(int)$o['total_minor'];$snapshot=json_decode($o['snapshot_json'],true);$actorId=(int)$actor['id'];
 if($action==='confirm'){
  if($o['kind']!=='deposit'||$status!=='new')throw new ApiError('Заявка уже обработана',409);$bankref=txt($d,'bankref',150);$total=minor($d['amount']??'',cfg()['max_amount_minor']);$result=txt($d,'text',5000,false);if($total!==(int)$o['amount_minor']&&($d['amountVerified']??false)!==true)throw new ApiError('Сумма отличается от заявки. Перепроверьте поступление и подтвердите корректность суммы.');if(one('SELECT number FROM pm_operations WHERE bank_reference=?',[$bankref]))throw new ApiError('Это банковское поступление уже зачислено',409);$balance+=$total;$status='completed';ledger($id,'deposit',$total,0,$actorId);notify((int)$c['id'],$actorId,'Поступление по заявке №'.$id.' подтверждено. Зачислено '.number_format($total/100,2,'.','').' RUB.'.($result!==''?' Пояснение: '.$result:''),$id);
 }elseif($action==='take'){
  if($o['kind']!=='order'||$status!=='new')throw new ApiError('Заявка уже взята в работу',409);$status='in_progress';$assigned=$actorId;
 }elseif(in_array($action,['complete','clarify'],true)){
  if(!in_array($o['kind'],['order','refund'],true)||$status!=='in_progress'||(int)$assigned!==$actorId)throw new ApiError('Сначала возьмите заявку в работу',409);$comment=txt($d,'text');
  if($o['kind']==='refund'&&$action==='clarify')throw new ApiError('Отмените возврат с пояснением либо завершите после банковской выплаты');if($o['kind']==='refund'){$bankref=txt($d,'bankref',150);if(one('SELECT number FROM pm_operations WHERE bank_reference=?',[$bankref]))throw new ApiError('Банковское подтверждение уже использовано',409);}
  if($action==='complete'){if($o['kind']==='order')$snapshot['executionProof']=txt($d,'proof',1000);$status='completed';$result=$comment;$balance-=$total;$reserved-=$total;ledger($id,'complete',-$total,-$total,$actorId);notify((int)$c['id'],$actorId,($o['kind']==='refund'?'Возврат выполнен. ':'Заказ выполнен. ').$comment,$id);}else{$status='needs_info';notify((int)$c['id'],$actorId,$comment,$id);}
 }elseif($action==='cancel'){
  if(!in_array($status,['new','in_progress','needs_info'],true))throw new ApiError('Заявка уже завершена',409);$reason=txt($d,'text');if(in_array($o['kind'],['order','refund'],true)){if($assigned&&(int)$assigned!==$actorId)throw new ApiError('Заявка закреплена за другим сотрудником',409);$reserved-=$total;ledger($id,'cancel',0,-$total,$actorId);}$status='cancelled';$result=$reason;notify((int)$c['id'],$actorId,'Заявка отменена. '.$reason,$id);
 }else throw new ApiError('Неизвестное действие');
 if($balance<0||$reserved<0||$balance<$reserved)throw new RuntimeException('Balance invariant failed');query('UPDATE pm_clients SET balance_minor=?,reserved_minor=? WHERE id=?',[$balance,$reserved,$c['id']]);query('UPDATE pm_operations SET status=?,assigned_to=?,bank_reference=?,result_text=?,total_minor=?,snapshot_json=?,updated_at=? WHERE number=?',[$status,$assigned,$bankref,$result,$total,json_encode($snapshot,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),now(),$id]);audit($actorId,$action,$id,['status'=>$status,'requested_minor'=>(int)$o['amount_minor'],'actual_minor'=>$o['kind']==='deposit'&&$status==='completed'?$total:null,'bank_reference'=>$bankref,'comment'=>$result,'proof'=>$snapshot['executionProof']??'','amount_verified'=>$action==='confirm'&&($d['amountVerified']??false)===true]);queue_operation_mail($id,$action);
 });
}
if(defined('PINA_LIBRARY_ONLY') && PHP_SAPI==='cli') return;
try {session_init();$route=preg_replace('~^/api/~','',parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH));$response=api_route($route,$_SERVER['REQUEST_METHOD']);if($_SERVER['REQUEST_METHOD']==='POST'&&isset(cfg()['smtp']))register_shutdown_function(function(){if(function_exists('fastcgi_finish_request'))fastcgi_finish_request();try{deliver_operation_mail(5);}catch(Throwable){error_log('Pina.market: notification delivery deferred');}});json_out($response);}
